// Smoke test for the flat C ABI in include/vibevoice_capi.h.
//
// Exercises the same TTS → wav → ASR roundtrip as test_closed_loop, but
// through the C API entry points (vv_capi_load / vv_capi_tts / vv_capi_asr)
// rather than the C++ orchestrators directly. This pins the symbols that
// LocalAI's purego backend will dlsym at runtime.
//
// Skips (return 77) unless VIBEVOICE_TTS_MODEL, VIBEVOICE_VOICE,
// VIBEVOICE_ASR_MODEL, VIBEVOICE_TOKENIZER are all set. Gated by
// VIBEVOICE_TEST_LARGE in CMake.

#include "vibevoice_capi.h"

#include <cctype>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <set>
#include <sstream>
#include <string>

namespace {

bool file_ok(const char* p) {
    if (!p || !*p) return false;
    FILE* f = std::fopen(p, "rb");
    if (!f) return false;
    std::fclose(f); return true;
}

std::set<std::string> word_set(const std::string& s) {
    std::string clean;
    clean.reserve(s.size());
    for (char c : s) {
        clean += std::isalnum(static_cast<unsigned char>(c))
                 ? static_cast<char>(std::tolower(static_cast<unsigned char>(c)))
                 : ' ';
    }
    std::set<std::string> out;
    std::istringstream iss(clean);
    for (std::string w; iss >> w; ) out.insert(w);
    return out;
}

std::string extract_content(const std::string& s) {
    const std::string key = "\"Content\":\"";
    std::string out;
    for (size_t pos = 0; (pos = s.find(key, pos)) != std::string::npos; ) {
        pos += key.size();
        size_t end = pos;
        while (end < s.size() && s[end] != '"') {
            end += (s[end] == '\\' && end + 1 < s.size()) ? 2 : 1;
        }
        if (!out.empty()) out += ' ';
        out.append(s, pos, end - pos);
        pos = end;
    }
    return out;
}

}  // namespace

int main() {
    const char* tts   = std::getenv("VIBEVOICE_TTS_MODEL");
    const char* voice = std::getenv("VIBEVOICE_VOICE");
    const char* asr   = std::getenv("VIBEVOICE_ASR_MODEL");
    const char* tok   = std::getenv("VIBEVOICE_TOKENIZER");
    if (!file_ok(tts) || !file_ok(voice) || !file_ok(asr) || !file_ok(tok)) {
        std::fprintf(stderr,
            "skip: capi test needs VIBEVOICE_{TTS_MODEL,VOICE,ASR_MODEL,"
            "TOKENIZER} all set.\n");
        return 77;
    }

    std::printf("[capi] %s\n", vv_capi_version());

    int rc = vv_capi_load(tts, asr, tok, voice, /*n_threads=*/0);
    if (rc != 0) { std::fprintf(stderr, "FAIL: vv_capi_load rc=%d\n", rc); return 1; }

    const std::string source = "Hello world this is a capi smoke test.";
    const std::string wav    = "/tmp/vibevoice_capi_smoke.wav";

    rc = vv_capi_tts(source.c_str(),
                     /*voice_path=*/nullptr,
                     /*ref_audio_paths=*/nullptr, /*n_ref=*/0,
                     wav.c_str(),
                     /*steps=*/20, /*cfg=*/1.3f,
                     /*max_speech_frames=*/200, /*seed=*/0xCAFE);
    if (rc != 0) { std::fprintf(stderr, "FAIL: vv_capi_tts rc=%d\n", rc); return 2; }

    char buf[8192] = {0};
    rc = vv_capi_asr(wav.c_str(), buf, sizeof(buf), /*max_new_tokens=*/256);
    if (rc <= 0) { std::fprintf(stderr, "FAIL: vv_capi_asr rc=%d\n", rc); return 3; }
    std::printf("[capi] asr: %s\n", buf);

    const std::string content = extract_content(buf);
    if (content.empty()) {
        std::fprintf(stderr, "FAIL: empty Content field\n"); return 4;
    }
    auto src_w = word_set(source);
    auto out_w = word_set(content);
    size_t hits = 0;
    for (const auto& w : src_w) if (out_w.count(w)) ++hits;
    const double recall = static_cast<double>(hits)
                        / static_cast<double>(src_w.size());
    std::printf("[capi] %zu/%zu source words recovered (%.1f%%)\n",
                hits, src_w.size(), recall * 100.0);
    if (recall < 0.6) {  // looser than closed-loop because TTS+ASR in same proc
        std::fprintf(stderr, "FAIL: recall %.2f < 0.60\n", recall);
        return 5;
    }

    vv_capi_unload();
    std::remove(wav.c_str());

    // ---- 1.5B path (optional) ----
    // If VIBEVOICE_TTS_15B_MODEL + VIBEVOICE_REF_WAV are set, exercise
    // the unified vv_capi_tts entry point with `ref_audio_path` (runtime
    // voice cloning) and round-trip through ASR. Skipped silently
    // otherwise so the existing realtime-only test still passes on
    // contributors who haven't downloaded the 1.5B gguf.
    const char* tts15b  = std::getenv("VIBEVOICE_TTS_15B_MODEL");
    const char* ref_wav = std::getenv("VIBEVOICE_REF_WAV");
    if (file_ok(tts15b) && file_ok(ref_wav)) {
        std::printf("[capi] 1.5b: loading %s\n", tts15b);
        rc = vv_capi_load(tts15b, asr, tok, /*voice_path=*/nullptr,
                          /*n_threads=*/0);
        if (rc != 0) { std::fprintf(stderr, "FAIL: vv_capi_load (1.5b) rc=%d\n", rc); return 6; }

        const std::string source15b = "Hello world this is a capi smoke test for runtime voice cloning.";
        const std::string wav15b    = "/tmp/vibevoice_capi_15b.wav";
        const char* refs[1] = { ref_wav };
        rc = vv_capi_tts(source15b.c_str(),
                         /*voice_path=*/nullptr,
                         /*ref_audio_paths=*/refs, /*n_ref=*/1,
                         wav15b.c_str(),
                         /*steps=*/20, /*cfg_scale=*/1.3f,
                         /*max_speech_frames=*/200, /*seed=*/0xCAFE);
        if (rc != 0) { std::fprintf(stderr, "FAIL: vv_capi_tts (1.5b) rc=%d\n", rc); return 7; }

        std::memset(buf, 0, sizeof(buf));
        rc = vv_capi_asr(wav15b.c_str(), buf, sizeof(buf), /*max_new_tokens=*/256);
        if (rc <= 0) { std::fprintf(stderr, "FAIL: vv_capi_asr (1.5b) rc=%d\n", rc); return 8; }
        std::printf("[capi] 1.5b asr: %s\n", buf);

        const std::string content15b = extract_content(buf);
        auto src15b = word_set(source15b);
        auto out15b = word_set(content15b);
        size_t hits15b = 0;
        for (const auto& w : src15b) if (out15b.count(w)) ++hits15b;
        const double recall15b = static_cast<double>(hits15b)
                                / static_cast<double>(src15b.size());
        std::printf("[capi] 1.5b %zu/%zu source words recovered (%.1f%%)\n",
                    hits15b, src15b.size(), recall15b * 100.0);
        if (recall15b < 0.6) {
            std::fprintf(stderr, "FAIL: 1.5b recall %.2f < 0.60\n", recall15b);
            return 9;
        }

        vv_capi_unload();
        std::remove(wav15b.c_str());
    }
    return 0;
}

// Streaming C ABI parity test for vv_capi_tts_stream (include/vibevoice_capi.h).
//
// Proves the callback path is bit-for-bit identical to the file path: the
// int16 PCM delivered to vv_pcm_cb, concatenated, must equal the PCM samples
// vv_capi_tts writes to a WAV for the same text/voice/seed. Same generate
// path, same float→int16 conversion (clamp + std::lround(x*32767)).
//
// Skips (return 77) unless VIBEVOICE_TTS_MODEL, VIBEVOICE_TOKENIZER,
// VIBEVOICE_VOICE are all set. Gated by VIBEVOICE_TEST_LARGE in CMake.

#include "vibevoice_capi.h"

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

namespace {

bool file_ok(const char* p) {
    if (!p || !*p) return false;
    FILE* f = std::fopen(p, "rb");
    if (!f) return false;
    std::fclose(f);
    return true;
}

// Read a 16-bit PCM WAV, stripping the canonical 44-byte header, into int16.
// vv_capi_tts writes exactly this layout (drwav RIFF/PCM16, mono, 24 kHz).
bool read_wav_pcm16(const char* path, std::vector<int16_t>* out) {
    FILE* f = std::fopen(path, "rb");
    if (!f) return false;
    std::fseek(f, 0, SEEK_END);
    long size = std::ftell(f);
    std::fseek(f, 0, SEEK_SET);
    if (size <= 44) { std::fclose(f); return false; }
    // Skip the 44-byte header (RIFF + fmt + data chunk headers).
    if (std::fseek(f, 44, SEEK_SET) != 0) { std::fclose(f); return false; }
    const size_t n_bytes  = static_cast<size_t>(size - 44);
    const size_t n_sample = n_bytes / sizeof(int16_t);
    out->resize(n_sample);
    size_t got = std::fread(out->data(), sizeof(int16_t), n_sample, f);
    std::fclose(f);
    return got == n_sample;
}

// Callback: append every streamed int16 sample into the sink vector.
int append_cb(const int16_t* samples, int n_samples, void* user) {
    auto* sink = static_cast<std::vector<int16_t>*>(user);
    sink->insert(sink->end(), samples, samples + n_samples);
    return 0;  // keep going
}

}  // namespace

int main() {
    const char* tts   = std::getenv("VIBEVOICE_TTS_MODEL");
    const char* tok   = std::getenv("VIBEVOICE_TOKENIZER");
    const char* voice = std::getenv("VIBEVOICE_VOICE");
    if (!file_ok(tts) || !file_ok(tok) || !file_ok(voice)) {
        std::fprintf(stderr,
            "skip: capi stream test needs VIBEVOICE_{TTS_MODEL,TOKENIZER,"
            "VOICE} all set.\n");
        return 77;
    }

    std::printf("[capi-stream] %s\n", vv_capi_version());

    int rc = vv_capi_load(tts, /*asr=*/nullptr, tok, voice, /*n_threads=*/0);
    if (rc != 0) { std::fprintf(stderr, "FAIL: vv_capi_load rc=%d\n", rc); return 1; }

    const char*    text  = "Hello world this is a streaming parity test.";
    const int      steps = 20;
    const float    cfg   = 1.3f;
    const int      maxfr = 200;
    const uint32_t seed  = 0xCAFE;

    // --- File path: vv_capi_tts → WAV → read PCM back. ---
    const char* wav = "/tmp/vibevoice_capi_stream.wav";
    rc = vv_capi_tts(text, /*voice_path=*/nullptr,
                     /*ref_audio_paths=*/nullptr, /*n_ref=*/0,
                     wav, steps, cfg, maxfr, seed);
    if (rc != 0) { std::fprintf(stderr, "FAIL: vv_capi_tts rc=%d\n", rc); return 2; }

    std::vector<int16_t> file_pcm;
    if (!read_wav_pcm16(wav, &file_pcm) || file_pcm.empty()) {
        std::fprintf(stderr, "FAIL: could not read PCM from %s\n", wav);
        return 3;
    }
    std::remove(wav);

    // --- Callback path: vv_capi_tts_stream → append int16. Same seed. ---
    std::vector<int16_t> stream_pcm;
    stream_pcm.reserve(file_pcm.size());
    rc = vv_capi_tts_stream(text, /*voice_path=*/nullptr,
                            steps, cfg, maxfr, seed, append_cb, &stream_pcm);
    if (rc != 0) { std::fprintf(stderr, "FAIL: vv_capi_tts_stream rc=%d\n", rc); return 4; }

    // --- Assert byte-identical. ---
    if (stream_pcm.size() != file_pcm.size()) {
        std::fprintf(stderr,
            "FAIL: sample count mismatch: stream=%zu file=%zu\n",
            stream_pcm.size(), file_pcm.size());
        return 5;
    }
    for (size_t i = 0; i < file_pcm.size(); ++i) {
        if (stream_pcm[i] != file_pcm[i]) {
            std::fprintf(stderr,
                "FAIL: sample %zu differs: stream=%d file=%d\n",
                i, stream_pcm[i], file_pcm[i]);
            return 6;
        }
    }

    std::printf("[capi-stream] OK: %zu int16 samples identical (callback == file)\n",
                file_pcm.size());
    vv_capi_unload();
    return 0;
}

// vibevoice_capi.h - flat C ABI for purego / dlopen integration.
//
// This is a *separate* header from vibevoice.h on purpose: it exposes a
// stateless, file-path-oriented surface that matches what
// LocalAI's go-purego backends expect (see backend/go/qwen3-tts-cpp/cpp/).
//
// Lifetime model: a single global engine, one load_model() per process,
// many tts() / asr() calls. Mirrors qwen3-tts-cpp exactly so a purego
// dlsym lookup and `purego.RegisterLibFunc` finds these symbols by name.
//
// Why a separate flat ABI instead of the existing vibevoice.h:
//   * No opaque pointers — purego pinning lifetimes is fiddly.
//   * No callee-allocated buffers — output via WAV path or caller-owned
//     char buffer.
//   * All return codes are int with 0 = success — every purego backend
//     in LocalAI expects exactly that.

#ifndef VIBEVOICE_CAPI_H
#define VIBEVOICE_CAPI_H

#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

// Loads the engine. Either or both model paths can be NULL:
//   tts_model_path  - realtime-0.5b gguf, required for vv_capi_tts.
//   asr_model_path  - asr-7b gguf,        required for vv_capi_asr.
//   tokenizer_path  - tokenizer gguf,     required for either.
//   voice_path      - voice gguf,         required for vv_capi_tts.
//                     Multiple voices: re-call with a different path,
//                     or pass NULL here and a per-call voice path to
//                     vv_capi_tts.
//   n_threads       - 0 → auto-detect.
// Returns 0 on success, non-zero error code otherwise. Idempotent —
// calling twice replaces the engine.
int vv_capi_load(const char* tts_model_path,
                 const char* asr_model_path,
                 const char* tokenizer_path,
                 const char* voice_path,
                 int         n_threads);

// Synthesize `text` into a 24 kHz mono WAV at `dst_wav_path`. The TTS
// path is selected by the loaded model's variant:
//
//   * realtime-0.5b -> uses `voice_path` (a pre-baked voice gguf).
//                      `ref_audio_paths` must be NULL / n_ref_audio == 0.
//   * 1.5b          -> uses `ref_audio_paths` — one WAV per speaker,
//                      24 kHz mono. `n_ref_audio_paths` is the number
//                      of distinct speakers (>= 1; the dialog in `text`
//                      can reference Speaker 0 .. n-1). `voice_path`
//                      must be NULL.
//
// `text` is either a plain sentence (single-speaker convenience —
// auto-wrapped as "Speaker 0: ...") or speaker-tagged dialog with one
// "Speaker N:" line per turn (passed through verbatim).
//
// `voice_path` may be NULL if already supplied to vv_capi_load.
// n_diffusion_steps == 0 -> 20, cfg_scale == 0 -> 1.3 (1.0 disables
// CFG), max_speech_frames == 0 -> 200, seed == 0 -> random.
int vv_capi_tts(const char*        text,
                const char*        voice_path,
                const char* const* ref_audio_paths,
                int                n_ref_audio_paths,
                const char*        dst_wav_path,
                int                n_diffusion_steps,
                float              cfg_scale,
                int                max_speech_frames,
                uint32_t           seed);

// Streaming counterpart of vv_capi_tts for the realtime-0.5B model. Each
// decoded audio window is converted to 24 kHz mono signed-16-bit PCM and handed
// to `on_pcm` as soon as it is produced. Concatenating every callback's samples
// yields exactly the PCM that vv_capi_tts writes to a WAV for the same
// text/voice/seed (same generate path, same float→int16 conversion).
//
//   text              - sentence or speaker-tagged dialog (see vv_capi_tts).
//   voice_path        - voice gguf; may be NULL if supplied to vv_capi_load.
//   n_diffusion_steps - 0 → 20. cfg_scale 0 → 1.3. max_speech_frames 0 → 200.
//   seed              - 0 → random.
//   on_pcm            - called per window; return non-zero to abort cleanly.
//   user              - opaque pointer forwarded to on_pcm.
//
// Realtime-0.5B only: returns -20 if a 1.5B model is loaded (unsupported).
// Returns 0 on success, non-zero error code otherwise.
typedef int (*vv_pcm_cb)(const int16_t* samples, int n_samples, void* user);
int vv_capi_tts_stream(const char* text,
                       const char* voice_path,
                       int         n_diffusion_steps,
                       float       cfg_scale,
                       int         max_speech_frames,
                       uint32_t    seed,
                       vv_pcm_cb   on_pcm,
                       void*       user);

// Transcribe `src_wav_path` into a JSON string written into the caller-
// owned `out_json` buffer of size `out_capacity`. The JSON is the same
// shape the model produces, e.g.
//   [{"Start":0.0,"End":2.8,"Speaker":0,"Content":"…"}]
// Returns:
//    > 0 on success — the number of bytes written (excluding the NUL
//                     terminator). The buffer is always NUL-terminated.
//      0 if no transcription was produced.
//    < 0 on error (see vv_status in vibevoice.h for the enum).
//   If out_capacity is smaller than the produced JSON, returns the
//   negative of the required size and writes the prefix that fit.
int vv_capi_asr(const char* src_wav_path,
                char*       out_json,
                size_t      out_capacity,
                int         max_new_tokens);

// Free engine state. Optional — process exit also frees it.
void vv_capi_unload(void);

// Build / version info. Returns a pointer to a static string; do not free.
const char* vv_capi_version(void);

// Deprecated: voice-cloning via the realtime-0.5B + ASR-7B path is not
// supported; the public realtime weights ship without encoders. Load
// a 1.5B gguf and call vv_capi_tts with `ref_audio_path` instead.
int vv_capi_voice_clone(const char* src_wav_path,
                        const char* dst_voice_gguf_path,
                        int         with_cfg);

#ifdef __cplusplus
}
#endif

#endif  // VIBEVOICE_CAPI_H

#ifndef VIBEVOICE_MODEL_LOADER_HPP
#define VIBEVOICE_MODEL_LOADER_HPP

// Lightweight gguf reader. Wraps ggml's gguf_* API with a name→tensor map
// and typed metadata accessors. Used by every component that needs to load
// weights (tokenizer, qwen2, acoustic_tokenizer, diffusion_head, ...).

#include "ggml-alloc.h"
#include "ggml-backend.h"
#include "ggml.h"
#include "gguf.h"

#include <cstdint>
#include <memory>
#include <string>
#include <unordered_map>
#include <vector>

namespace vv {

class ModelLoader {
public:
    ModelLoader();
    ~ModelLoader();

    ModelLoader(const ModelLoader&)            = delete;
    ModelLoader& operator=(const ModelLoader&) = delete;

    // Open the gguf file and load all tensor metadata + weight bytes into a
    // newly-created ggml_context. Tensors are looked up by name with `tensor`.
    bool load(const std::string& path);

    // Tensor lookup. Returns nullptr if not found.
    struct ggml_tensor* tensor(const std::string& name) const;
    bool                has(const std::string& name) const;

    // Cast all small (1-D / scalar / few-row) f16 tensors to f32 in-place.
    // ggml's CPU element-wise ops don't auto-cast f32 + f16, so norm scales,
    // biases, gammas and tiny embeddings need to be promoted up front when
    // the gguf was written in fp16. Large matmul weights stay fp16.
    //
    // `max_elems` is the size threshold (in scalar element count) for promotion.
    void promote_small_f16_to_f32(size_t max_elems = 65536);

    const std::vector<std::string>& tensor_names() const { return tensor_names_; }

    // Metadata accessors. Return the provided default if the key is absent or
    // wrong-typed.
    int32_t     get_i32(const std::string& key, int32_t       def = 0)  const;
    int64_t     get_i64(const std::string& key, int64_t       def = 0)  const;
    uint32_t    get_u32(const std::string& key, uint32_t      def = 0)  const;
    float       get_f32(const std::string& key, float         def = 0)  const;
    bool        get_bool(const std::string& key, bool         def = false) const;
    std::string get_str(const std::string& key, const std::string& def = {}) const;
    std::vector<int32_t> get_i32_array(const std::string& key) const;
    std::vector<std::string> get_str_array(const std::string& key) const;

    // Raw access if a caller needs more.
    struct gguf_context* gguf_ctx() const { return gguf_; }
    struct ggml_context* ggml_ctx() const { return ctx_; }

private:
    struct gguf_context*      gguf_           = nullptr;
    struct ggml_context*      ctx_            = nullptr;  // tensor metadata
    struct ggml_context*      promote_ctx_    = nullptr;  // f32 promoted tensors
    ggml_backend_buffer_t     backend_buffer_ = nullptr;  // owns the actual weight data
    ggml_backend_buffer_t     promote_buffer_ = nullptr;  // owns promoted weight data
    std::vector<std::string>  tensor_names_;
    std::unordered_map<std::string, struct ggml_tensor*> tensor_by_name_;
};

}  // namespace vv

#endif  // VIBEVOICE_MODEL_LOADER_HPP

// vibevoice_capi.cpp - flat C ABI implementation.
//
// Wraps the C++ orchestrators (vv::vibevoice_load, vv::vibevoice_tts_generate,
// vv::vibevoice_asr_transcribe) in a single global-state surface that
// LocalAI's purego backends consume (see vibevoice_capi.h).

#include "vibevoice_capi.h"

#include "audio_io.hpp"
#include "common.hpp"
#include "vibevoice_asr.hpp"
#include "vibevoice_tts.hpp"

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstring>
#include <memory>
#include <mutex>
#include <string>
#include <vector>

namespace {

struct GlobalEngine {
    std::unique_ptr<vv::VibeVoiceModel> tts;
    std::unique_ptr<vv::VibeVoiceModel> asr;
    std::unique_ptr<vv::VibeVoiceVoice> voice;
    std::string                          voice_path_loaded;
    std::string                          ref_audio_path_loaded;  // 1.5b
    int                                  n_threads = 4;
    std::mutex                           mu;
};

GlobalEngine& engine() {
    static GlobalEngine g;
    return g;
}

bool ensure_voice_loaded(GlobalEngine& g, const char* voice_path) {
    if (!voice_path || !voice_path[0]) return g.voice != nullptr;
    if (g.voice && g.voice_path_loaded == voice_path) return true;
    if (!g.tts) {
        VV_LOG_ERROR("vv_capi: TTS model required to load a voice");
        return false;
    }
    auto v = std::make_unique<vv::VibeVoiceVoice>();
    if (!vv::vibevoice_voice_load(voice_path, *g.tts, v.get())) {
        VV_LOG_ERROR("vv_capi: voice load failed: %s", voice_path);
        return false;
    }
    g.voice              = std::move(v);
    g.voice_path_loaded  = voice_path;
    return true;
}

}  // namespace

extern "C" {

int vv_capi_load(const char* tts_model_path,
                 const char* asr_model_path,
                 const char* tokenizer_path,
                 const char* voice_path,
                 int         n_threads) {
    auto& g = engine();
    std::lock_guard<std::mutex> lk(g.mu);

    if (!tokenizer_path || !tokenizer_path[0]) {
        VV_LOG_ERROR("vv_capi_load: tokenizer_path is required");
        return -2;
    }
    if ((!tts_model_path || !tts_model_path[0]) &&
        (!asr_model_path || !asr_model_path[0])) {
        VV_LOG_ERROR("vv_capi_load: at least one of tts_model_path or asr_model_path is required");
        return -2;
    }

    g.tts.reset();
    g.asr.reset();
    g.voice.reset();
    g.voice_path_loaded.clear();
    g.n_threads = n_threads > 0 ? n_threads : 4;

    // Each VibeVoiceModel has its own Tokenizer member, but the tokenizer
    // backing data is loaded from the same gguf each time and `load_from_file`
    // refuses to run twice on a single Tokenizer instance. We use a fresh
    // Tokenizer per model — both load OK because each is a different
    // instance.
    if (tts_model_path && tts_model_path[0]) {
        auto m = std::make_unique<vv::VibeVoiceModel>();
        if (!vv::vibevoice_load(tts_model_path, m.get())) {
            VV_LOG_ERROR("vv_capi_load: TTS model load failed: %s", tts_model_path);
            return -3;
        }
        if (!m->tokenizer.load_from_file(tokenizer_path)) {
            VV_LOG_ERROR("vv_capi_load: TTS tokenizer load failed: %s", tokenizer_path);
            return -7;
        }
        g.tts = std::move(m);
    }

    if (asr_model_path && asr_model_path[0]) {
        auto m = std::make_unique<vv::VibeVoiceModel>();
        if (!vv::vibevoice_load(asr_model_path, m.get())) {
            VV_LOG_ERROR("vv_capi_load: ASR model load failed: %s", asr_model_path);
            return -3;
        }
        if (!m->tokenizer.load_from_file(tokenizer_path)) {
            VV_LOG_ERROR("vv_capi_load: ASR tokenizer load failed: %s", tokenizer_path);
            return -7;
        }
        g.asr = std::move(m);
    }

    if (voice_path && voice_path[0]) {
        if (!ensure_voice_loaded(g, voice_path)) return -3;
    }
    return 0;
}

int vv_capi_tts(const char*        text,
                const char*        voice_path,
                const char* const* ref_audio_paths,
                int                n_ref_audio_paths,
                const char*        dst_wav_path,
                int                n_diffusion_steps,
                float              cfg_scale,
                int                max_speech_frames,
                uint32_t           seed) {
    auto& g = engine();
    std::lock_guard<std::mutex> lk(g.mu);
    if (!g.tts)             return -3;
    if (!text || !dst_wav_path) return -2;

    const bool is_15b = (g.tts->variant == "1.5b");

    vv::VibeVoiceTTSParams p;
    p.cfg_scale          = cfg_scale > 0.0f ? cfg_scale : 1.3f;
    p.n_diffusion_steps  = n_diffusion_steps > 0 ? n_diffusion_steps : 20;
    p.max_speech_frames  = max_speech_frames > 0 ? max_speech_frames : 200;
    p.seed               = seed;
    p.verbose            = false;

    if (is_15b) {
        // 1.5B path: ref_audio_paths is required (per call or via load).
        if (n_ref_audio_paths > 0 && ref_audio_paths) {
            for (int i = 0; i < n_ref_audio_paths; ++i) {
                if (ref_audio_paths[i] && ref_audio_paths[i][0]) {
                    p.ref_audio_paths.emplace_back(ref_audio_paths[i]);
                }
            }
        }
        if (p.ref_audio_paths.empty() && !g.ref_audio_path_loaded.empty()) {
            p.ref_audio_paths.push_back(g.ref_audio_path_loaded);
        }
        if (p.ref_audio_paths.empty()) {
            VV_LOG_ERROR("vv_capi_tts: 1.5b model needs at least one "
                         "ref_audio_paths entry (per-call or via vv_capi_load)");
            return -2;
        }
    } else {
        // realtime-0.5b path: voice_path required (per call or via load).
        if (voice_path && voice_path[0]) {
            if (!ensure_voice_loaded(g, voice_path)) return -3;
        }
        if (!g.voice) {
            VV_LOG_ERROR("vv_capi_tts: no voice loaded — pass voice_path "
                         "here or to vv_capi_load");
            return -2;
        }
        p.voice = g.voice.get();
    }

    std::vector<float> samples;
    int rc = vv::vibevoice_tts_generate(g.tts.get(), text, p, &samples);
    if (rc != 0) {
        VV_LOG_ERROR("vv_capi_tts: generate rc=%d", rc);
        return rc;
    }

    vv_audio audio_out{};
    audio_out.samples     = samples.data();
    audio_out.n_samples   = samples.size();
    audio_out.sample_rate = 24000;
    audio_out.channels    = 1;
    return vv::save_wav_pcm16(dst_wav_path, audio_out);
}

int vv_capi_tts_stream(const char* text,
                       const char* voice_path,
                       int         n_diffusion_steps,
                       float       cfg_scale,
                       int         max_speech_frames,
                       uint32_t    seed,
                       vv_pcm_cb   on_pcm,
                       void*       user) {
    auto& g = engine();
    std::lock_guard<std::mutex> lk(g.mu);
    if (!g.tts)          return -3;
    if (!text || !on_pcm) return -2;

    // Realtime-0.5B only: the streaming decoder is not wired for the 1.5B
    // variant (see vibevoice_tts_generate_streaming). Report a distinct code.
    if (g.tts->variant == "1.5b") {
        VV_LOG_ERROR("vv_capi_tts_stream: streaming unsupported for 1.5b model");
        return -20;
    }

    vv::VibeVoiceTTSParams p;
    p.cfg_scale          = cfg_scale > 0.0f ? cfg_scale : 1.3f;
    p.n_diffusion_steps  = n_diffusion_steps > 0 ? n_diffusion_steps : 20;
    p.max_speech_frames  = max_speech_frames > 0 ? max_speech_frames : 200;
    p.seed               = seed;
    p.verbose            = false;

    if (voice_path && voice_path[0]) {
        if (!ensure_voice_loaded(g, voice_path)) return -3;
    }
    if (!g.voice) {
        VV_LOG_ERROR("vv_capi_tts_stream: no voice loaded — pass voice_path "
                     "here or to vv_capi_load");
        return -2;
    }
    p.voice = g.voice.get();

    // Reused int16 buffer. Convert each float window with the EXACT same
    // clamp + round as save_wav_pcm16 (audio_io.cpp) so the concatenated
    // callback stream is byte-identical to the WAV vv_capi_tts writes.
    std::vector<int16_t> buf;
    auto on_chunk = [&](const float* s, int n) -> bool {
        buf.resize(static_cast<size_t>(n));
        for (int i = 0; i < n; ++i) {
            float x = std::max(-1.0f, std::min(1.0f, s[i]));
            buf[static_cast<size_t>(i)] =
                static_cast<int16_t>(std::lround(x * 32767.0f));
        }
        // Non-zero from the caller means abort → stop generation cleanly.
        return on_pcm(buf.data(), n, user) == 0;
    };

    int rc = vv::vibevoice_tts_generate_streaming(g.tts.get(), text, p, on_chunk);
    if (rc != 0) {
        VV_LOG_ERROR("vv_capi_tts_stream: generate rc=%d", rc);
        return rc;
    }
    return 0;
}

int vv_capi_asr(const char* src_wav_path,
                char*       out_json,
                size_t      out_capacity,
                int         max_new_tokens) {
    auto& g = engine();
    std::lock_guard<std::mutex> lk(g.mu);
    if (!g.asr)                    return -3;
    if (!src_wav_path || !out_json || out_capacity == 0) return -2;

    std::vector<float> audio;
    if (vv::load_wav_24k_mono(src_wav_path, &audio) != 0 || audio.empty()) {
        VV_LOG_ERROR("vv_capi_asr: failed to load wav: %s", src_wav_path);
        return -8;
    }

    vv::VibeVoiceASRParams p;
    p.max_new_tokens     = max_new_tokens > 0 ? max_new_tokens : 256;
    p.repetition_penalty = 1.0f;
    p.no_repeat_ngram    = 0;
    p.verbose            = false;

    std::string transcript;
    int rc = vv::vibevoice_asr_transcribe(g.asr.get(), audio, p, &transcript);
    if (rc != 0) {
        VV_LOG_ERROR("vv_capi_asr: transcribe rc=%d", rc);
        return rc;
    }
    if (transcript.empty()) {
        out_json[0] = '\0';
        return 0;
    }

    const size_t need = transcript.size() + 1;  // +1 for NUL
    if (need > out_capacity) {
        // Write the prefix that fits, NUL-terminate, and report the
        // required size negatively so the caller can grow + retry.
        std::memcpy(out_json, transcript.data(), out_capacity - 1);
        out_json[out_capacity - 1] = '\0';
        return -static_cast<int>(need);
    }
    std::memcpy(out_json, transcript.data(), transcript.size());
    out_json[transcript.size()] = '\0';
    return static_cast<int>(transcript.size());
}

void vv_capi_unload(void) {
    auto& g = engine();
    std::lock_guard<std::mutex> lk(g.mu);
    g.voice.reset();
    g.tts.reset();
    g.asr.reset();
    g.voice_path_loaded.clear();
}

const char* vv_capi_version(void) { return "vibevoice.cpp 0.1.0 (capi)"; }

